mapper.select:
SELECT p.project_sq AS projectSq, p.project_ttl AS projectTtl, p.company_sq AS companySq, c.company_nm AS companyNm, u.user_sq AS userSq, u.user_id AS userId, p.project_recruit_start_dt AS recruitStartDt, p.project_recruit_end_dt AS recruitEndDt, p.project_start_dt AS projectStartDt, p.project_end_dt AS projectEndDt, AS recruitStatus, p.project_salary AS projectSalary, p.project_salary_negotiable_yn AS salaryNegotiableYn, p.project_view_cnt AS viewCnt, p.project_scrap_cnt AS scrapCnt, (SELECT COUNT(*) FROM TBL_PROJECT_APPLICATION_H a WHERE a.project_sq = p.project_sq) AS applicationCnt, p.project_is_deleted_yn AS isDeletedYn, p.project_created_at_dtm AS createdAt
ORDER BY
p.project_sq p.project_ttl c.company_nm p.project_recruit_end_dt p.project_salary p.project_view_cnt applicationCnt p.project_created_at_dtm ${sortOrder} LIMIT #{size} OFFSET #{offset}

mapper.update:
UPDATE TBL_PROJECT_M
project_ttl = #{dto.projectTtl}, project_salary = #{dto.projectSalary}, project_salary_negotiable_yn = #{dto.salaryNegotiableYn}, project_recruit_start_dt = #{dto.recruitStartDt}, project_recruit_end_dt = #{dto.recruitEndDt}, project_start_dt = #{dto.projectStartDt}, project_end_dt = #{dto.projectEndDt}, project_description_txt = #{dto.descriptionTxt}, project_preference_txt = #{dto.preferenceTxt}, project_modified_at_dtm = NOW()
WHERE project_sq = #{projectSq}
